</style></head><body><nav class="nav"><div class="wrap"><a class="logo" href="home.php">เที่ยว ตาก · TAK EXPLORE</a></div></nav><header class="hero"><div class="wrap"><div class="ey">ADD A NEW DESTINATION</div><h1>เพิ่มสถานที่เที่ยว</h1><p>แชร์สถานที่ที่คุณคิดว่านักเดินทางคนอื่นควรรู้จัก</p></div></header><main class="wrap"><form class="form" method="POST" action="process-add-place.php" enctype="multipart/form-data"><section class="panel"><h2>ข้อมูลสถานที่</h2><div class="field"><label>ชื่อสถานที่</label><input name="name_place" required placeholder="เช่น จุดชมวิว..."></div><div class="field"><label>ที่ตั้ง</label><input name="location_place" required placeholder="เช่น อ.เมืองตาก"></div><div class="field"><label>หมวดหมู่</label><input name="category_place" placeholder="เช่น น้ำตก / จุดชมวิว / ภูเขา"></div><div class="field"><label>รายละเอียด</label><textarea name="description_place" placeholder="เล่าเกี่ยวกับสถานที่"></textarea></div><div class="field"><label>รูปสถานที่ (เพิ่มได้หลายรูป)</label><div id="place-image-list" class="image-upload-list"><div class="image-upload-row"><input type="file" name="image_place[]" accept="image/jpeg,image/png"><button type="button" class="image-remove" aria-label="ลบช่องรูป" disabled>×</button></div></div><button type="button" id="add-place-image" class="image-add">＋ เพิ่มช่องรูป</button><small style="display:block;margin-top:8px;color:#68736c">เพิ่มช่องทีละรูป และลบช่องที่ไม่ต้องการได้</small></div></section><section class="panel"><h2>ปักหมุดสถานที่</h2><div class="hint">คลิกบนแผนที่เพื่อวางหมุด แล้วลากหมุดเพื่อปรับตำแหน่ง</div><div id="map"></div><div class="row"><div class="field"><label>ละติจูด</label><input id="lat" name="lat_place" readonly required></div><div class="field"><label>ลองจิจูด</label><input id="lng" name="lng_place" readonly required></div></div><button class="submit" id="submit" disabled>ปักหมุดก่อนบันทึก</button></section></form></main><script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"></script><script>
const map=L.map('map').setView([16.95,98.85],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map);let marker=null;function set(p){if(!marker)marker=L.marker(p,{draggable:true}).addTo(map);else marker.setLatLng(p);document.getElementById('lat').value=p.lat.toFixed(7);document.getElementById('lng').value=p.lng.toFixed(7);document.getElementById('submit').disabled=false;document.getElementById('submit').textContent='บันทึกสถานที่นี้'}map.on('click',e=>set(e.latlng));
const placeImageList=document.getElementById('place-image-list');const addPlaceImage=document.getElementById('add-place-image');
function refreshPlaceImageRemove(){const rows=[...placeImageList.querySelectorAll('.image-upload-row')];rows.forEach(row=>row.querySelector('.image-remove').disabled=rows.length===1)}
addPlaceImage.addEventListener('click',()=>{const row=document.createElement('div');row.className='image-upload-row';row.innerHTML='<input type="file" name="image_place[]" accept="image/jpeg,image/png"><button type="button" class="image-remove" aria-label="ลบช่องรูป">×</button>';row.querySelector('.image-remove').addEventListener('click',()=>{row.remove();refreshPlaceImageRemove()});placeImageList.appendChild(row);refreshPlaceImageRemove()});refreshPlaceImageRemove();</script><?php include("global-search.php"); ?></body></html>